const body = $json.body || $json;
const operacao = typeof body.operacao === 'string' ? body.operacao.trim() : '';
const idEmpresa = typeof body.idEmpresa === 'string' ? body.idEmpresa.trim() : '';
const requestId = (typeof body.requestId === 'string' && body.requestId.trim().length > 0)
  ? body.requestId.trim()
  : ('sem-request-id-' + Date.now());
const dadosBrutos = (body.dados && typeof body.dados === 'object') ? body.dados : {};

// Única operação reconhecida por este workflow — o APP-WF020 é exclusivo para
// comandos/mutações da Agenda (ver n8n/documentacao/app/APP-WF020.md). Nunca reconhece
// operações de leitura (essas continuam no APP-WF019, que permanece read-only) nem
// comandos futuros ainda não implementados (agenda.criar/reagendar/concluir) —
// adicioná-los exige voltar aqui E ao fluxo real, mesmo padrão do APP-WF019.
const OPERACOES_SUPORTADAS = ['agenda.cancelar'];

const idAgendamento = typeof dadosBrutos.idAgendamento === 'string' ? dadosBrutos.idAgendamento.trim() : '';
const motivoBruto = typeof dadosBrutos.motivo === 'string' ? dadosBrutos.motivo : '';
// Defesa em profundidade: o NestJS já normaliza/trima/limita o motivo antes de enviar
// (ver agenda.service.ts/agenda-cancelar.dto.ts), mas o workflow nunca confia
// cegamente nisso — reaplica aqui um corte de segurança equivalente (nunca grava um
// texto com HTML ou arbitrariamente grande na planilha).
const motivo = motivoBruto.replace(/[<>]/g, '').trim().slice(0, 500);
const chamadorPerfil = typeof dadosBrutos.chamadorPerfil === 'string' ? dadosBrutos.chamadorPerfil : '';
const chamadorIdProfissional = typeof dadosBrutos.chamadorIdProfissional === 'string' ? dadosBrutos.chamadorIdProfissional : '';

let erro_codigo = '';
let erro_mensagem = '';

if (!operacao) {
  erro_codigo = 'VALIDATION_ERROR';
  erro_mensagem = 'operacao é obrigatória.';
} else if (!idEmpresa) {
  erro_codigo = 'TENANT_REQUIRED';
  erro_mensagem = 'idEmpresa é obrigatório.';
} else if (!OPERACOES_SUPORTADAS.includes(operacao)) {
  erro_codigo = 'INVALID_OPERATION';
  erro_mensagem = 'Operação "' + operacao + '" não é reconhecida pelo APP-WF020.';
} else if (!idAgendamento) {
  erro_codigo = 'VALIDATION_ERROR';
  erro_mensagem = 'dados.idAgendamento é obrigatório.';
}

return [{ json: { operacao, idEmpresa, requestId, idAgendamento, motivo, chamadorPerfil, chamadorIdProfissional, erro_codigo, erro_mensagem } }];

// Localiza o agendamento SEMPRE por idEmpresa + ID_AGENDAMENTO (nunca só por
// ID_AGENDAMENTO) — GS - Buscar Agendamento já filtra pelos dois; este node nunca
// confia cegamente nisso e reforça a checagem de duplicidade abaixo (mesmo padrão de
// hardening já usado em CODE - Normalizar Empresa, APP-WF019).
//
// "Não encontrado" e "encontrado mas pertence a outro profissional" (quando o chamador
// é profissional) convergem PROPOSITALMENTE no mesmo NOT_FOUND genérico — nunca revela
// a um profissional que um agendamento de outro colega existe (mesmo princípio de
// buscarPorId em Clientes/Serviços/Profissionais no NestJS).
//
// STATUS: só AGENDADO pode transicionar para CANCELADO. CONCLUIDO é CONFLICT (não pode
// cancelar um atendimento já concluído). CANCELADO é IDEMPOTENTE — repetir o
// cancelamento de algo já cancelado é sucesso, sem tocar a planilha de novo (nunca
// reescreve DATA_CANCELAMENTO/MOTIVO_CANCELAMENTO já gravados por uma chamada
// anterior). Qualquer outro valor de STATUS é dado corrompido — nunca inventa uma
// transição para um valor fora da whitelist real (AGENDADO/CONCLUIDO/CANCELADO).
//
// Google Calendar (GOOGLE_EVENT_ID) é DELIBERADAMENTE não lido/tocado nesta fase — ver
// sticky note desta workflow: decisão de adiar a sincronização até existir uma regra
// inequívoca de resolução do calendário (PROFISSIONAIS.GOOGLE_CALENDAR_ID x
// EMPRESAS.GOOGLE_CALENDAR_ID), nunca inventada aqui.
const contexto = $('CODE - Validar Envelope').first().json;
const requestId = contexto.requestId;
const idAgendamentoSolicitado = contexto.idAgendamento;
const motivo = contexto.motivo;
const chamadorPerfil = contexto.chamadorPerfil;
const chamadorIdProfissional = contexto.chamadorIdProfissional;

function campoPresente(valor) {
  if (valor === undefined || valor === null) return false;
  if (typeof valor === 'string' && valor.trim() === '') return false;
  return true;
}

function erro(codigo, mensagem) {
  return [{ json: { erro_codigo: codigo, erro_mensagem: mensagem, requestId } }];
}

const linhas = $input.all().map((item) => item.json);
const reais = linhas.filter((row) => row && campoPresente(row.ID_AGENDAMENTO));

if (reais.length > 1) {
  // Duplicidade acidental na fonte para o mesmo ID_AGENDAMENTO dentro do mesmo tenant —
  // nunca escolher uma linha silenciosamente. Mensagem genérica, nunca revela detalhe.
  return erro('UPSTREAM_ERROR', 'Não foi possível processar o cancelamento no momento.');
}

if (reais.length === 0) {
  return erro('NOT_FOUND', 'Agendamento não encontrado.');
}

const row = reais[0];

if (chamadorPerfil === 'profissional' && String(row.ID_PROFISSIONAL || '') !== String(chamadorIdProfissional || '')) {
  return erro('NOT_FOUND', 'Agendamento não encontrado.');
}

const status = typeof row.STATUS === 'string' ? row.STATUS.trim().toUpperCase() : '';

if (status === 'CONCLUIDO') {
  return erro('CONFLICT', 'Este atendimento já foi concluído e não pode ser cancelado.');
}

if (status === 'CANCELADO') {
  return [{ json: {
    requestId,
    idAgendamento: idAgendamentoSolicitado,
    precisaCancelar: false,
    erro_codigo: '',
  } }];
}

if (status !== 'AGENDADO') {
  return erro('UPSTREAM_ERROR', 'Não foi possível processar o cancelamento no momento.');
}

const agora = new Date().toISOString();
return [{ json: {
  requestId,
  idAgendamento: idAgendamentoSolicitado,
  precisaCancelar: true,
  erro_codigo: '',
  motivoNormalizado: motivo || 'Cancelado pelo usuário',
  dataCancelamento: agora,
  ultimaAtualizacao: agora,
} }];

// Compartilhado entre "erro técnico ao buscar" e "erro técnico ao cancelar" — mensagem
// genérica de propósito, nunca expõe detalhe do Google Sheets.
const requestId = $('CODE - Validar Envelope').first().json.requestId;
return [{ json: {
  erro_codigo: 'UPSTREAM_ERROR',
  erro_mensagem: 'Não foi possível processar o cancelamento no momento.',
  requestId,
} }];

// Compartilhado pelos dois desfechos de sucesso de agenda.cancelar: cancelamento
// idempotente (já estava CANCELADO, nenhuma escrita nova) e cancelamento efetivo (GS -
// Cancelar Agendamento acabou de gravar). Os dois convergem aqui sem Merge, lendo o
// contexto de CODE - Localizar E Validar Agendamento — nunca confia no shape bruto
// devolvido pelo node do Google Sheets.
const contexto = $('CODE - Localizar E Validar Agendamento').first().json;
return [{ json: {
  ok: true,
  data: { idAgendamento: contexto.idAgendamento, status: 'CANCELADO' },
  meta: { requestId: contexto.requestId },
} }];

// Alimentado por múltiplas origens mutuamente exclusivas (envelope inválido, erro
// técnico ao buscar/cancelar, ou regra de negócio violada em CODE - Localizar E Validar
// Agendamento) — todas conectadas diretamente na mesma entrada (nunca um Merge; ver
// sticky note desta workflow). Nunca expõe stack, payload bruto do Sheets, credencial
// ou API key — só code/message já decididos antes.
return [{ json: {
  ok: false,
  error: { code: $json.erro_codigo, message: $json.erro_mensagem },
  meta: { requestId: $json.requestId },
} }];
